<script setup lang="ts">import {ref} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {create} from '../api/scenarios';import {create as run} from '../api/runs';import {useAsync} from '../hooks/useAsync';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{go:[string]}>();const name=ref(''),profile=ref(''),windows=ref(3),candidate=ref<number|null>(4),arrival=ref(1),service=ref(1),duration=ref(480),warmup=ref(120),reps=ref(30),seed=ref(2206),formError=ref('');const {busy,error,execute}=useAsync();async function submit(){formError.value='';if(candidate.value!==null&&(!Number.isInteger(candidate.value)||candidate.value<1||candidate.value>12)){formError.value='候选窗口数须为1—12的整数；留空则保存为单方案。';return}if(candidate.value!==null&&candidate.value===windows.value)formError.value='基准与候选窗口数相同，逐次差值必为0；可用于对照自检，通常应选择不同窗口。';await execute(async()=>{if(!name.value)return;await create({name:name.value,profile_id:profile.value||props.data.profiles[0]?.id,windows:windows.value,candidate_windows:candidate.value,arrival_multiplier:arrival.value,service_multiplier:service.value,duration_minutes:duration.value,warmup_minutes:warmup.value,replications:reps.value,seed:seed.value});name.value='';await props.refresh()})}async function launch(id:string){await execute(async()=>{await run({scenario_id:id});await props.refresh();emit('go','results')})};
</script><template><PageHeading code="04 / COUNTER SCENARIOS" title="窗口数之外，把假设也写下来。" description="到达倍率作用于λ，服务倍率作用于单窗口μ。填写候选窗口数即启用配对试验：同一剖面、同一批到达与服务、相同种子，逐次比较等待差。留空则沿用旧式单方案预演。"/><section v-if="canWrite" class="paper"><h2>新建窗口预演</h2><form class="scenario-form" @submit.prevent="submit"><label>方案名称<input aria-label="方案名称" v-model="name" required minlength="2"/></label><label>输入剖面<select aria-label="输入剖面" v-model="profile"><option value="" disabled>默认使用最新剖面</option><option v-for="p in data.profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>基准窗口数 c<input aria-label="基准窗口数" type="number" min="1" max="12" v-model.number="windows"/></label><label>候选窗口数 c<input aria-label="候选窗口数" type="number" min="1" max="12" placeholder="留空=单方案" v-model.number="candidate"/></label><label>到达倍率<input type="number" min=".2" max="3" step=".1" v-model.number="arrival"/></label><label>服务倍率<input type="number" min=".2" max="3" step=".1" v-model.number="service"/></label><label>观测时域 / 分钟<input type="number" min="60" max="1440" v-model.number="duration"/></label><label>预热 / 分钟<input type="number" min="0" max="1440" v-model.number="warmup"/></label><label>重复次数<input aria-label="重复次数" type="number" min="5" max="100" v-model.number="reps"/></label><label>随机种子<input type="number" min="0" v-model.number="seed"/></label><button :disabled="busy">{{candidate!==null?'保存配对方案':'保存单方案'}}</button></form><p class="caption">{{candidate!==null?'配对：两侧共用同一剖面与随机参数，每次重复共用到达与服务，逐次计算基准−候选的等待差。':'单方案：只比较各次预演均值，随机波动仍可能被当成收益。'}}</p></section><Notice v-if="formError" error>{{formError}}</Notice><Notice v-if="error" error>{{error}}</Notice><section class="paper"><h2>已保存方案</h2><article v-for="s in data.scenarios" :key="s.id" class="scenario-row"><div class="counter-number">{{s.candidate_windows?`${s.windows}→${s.candidate_windows}`:s.windows}}<small>{{s.candidate_windows?'PAIRED':'WINDOWS'}}</small></div><div class="scenario-detail"><h3>{{s.name}}</h3><p>{{data.profiles.find(p=>p.id===s.profile_id)?.name}}</p><small>观测{{s.duration_minutes}}分钟 · 预热{{s.warmup_minutes}}分钟 · {{s.replications}}次重复 · seed {{s.seed}}{{s.candidate_windows?' · 配对试验':''}}</small></div><button class="secondary" v-if="canWrite" :disabled="busy" @click="launch(s.id)">运行预演　→</button></article></section><section class="paper"><h2>运行队列</h2><div class="table-scroll"><table><thead><tr><th>窗口方案</th><th>试验模式</th><th>状态</th><th>提交时间</th></tr></thead><tbody><tr v-for="r in data.runs" :key="r.id"><td>{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}}</td><td>{{data.scenarios.find(s=>s.id===r.scenario_id)?.candidate_windows?'配对试验':'单方案'}}</td><td><Status :value="r.status"/></td><td>{{r.created_at.slice(0,19).replace('T',' ')}}</td></tr></tbody></table></div></section></template>
